body[data-theme="cyberpunk"] {
  --ink: #080406;
  --panel: #12080a;
  --panel-raised: #1b0b0f;
  --line: #4a1018;
  --muted: #a88487;
  --paper: #f3e7e8;
  --green: #ed1b2e;
  --green-dim: #8b1020;
  --cyan: #ff727b;
  --grid-line: rgba(237, 27, 46, .035);
  --orb-core: #080406;
  --orb-glow: #ed1b2e;
}
.route-bar, .route-bar a, #route-page { color: var(--green); }
.route-bar { gap: 4px; }
.page-controls { justify-content: space-between; }
.keyboard-hint { margin-left: 0; }
.theme-picker { position: relative; z-index: 8; flex: 0 0 56px; margin-left: 0; }
.theme-toggle { width: 56px; min-width: 56px; height: 56px; display: grid; place-items: center; padding: 0; border: 0; background: transparent; cursor: pointer; }
.theme-orb { position: relative; width: 30px; height: 30px; border-radius: 50%; background: radial-gradient(circle, var(--orb-core) 0 39%, color-mix(in srgb, var(--orb-glow) 75%, var(--orb-core)) 74%, var(--orb-glow) 100%); box-shadow: 0 0 13px 3px var(--orb-glow), inset 0 0 12px var(--orb-glow); transition: transform .2s ease, box-shadow .2s ease; }
.theme-orb::before { position: absolute; inset: -7px; border: 1px solid var(--green); border-radius: 50%; content: ""; }
.theme-toggle:hover .theme-orb, .theme-toggle[aria-expanded="true"] .theme-orb { transform: scale(1.06); box-shadow: 0 0 18px 4px var(--orb-glow), inset 0 0 12px var(--orb-glow); }
.theme-menu { position: absolute; left: 0; bottom: calc(100% + 8px); width: 240px; display: grid; padding: 5px; border: 1px solid var(--green); background: var(--panel-raised); box-shadow: 0 12px 28px rgba(0, 0, 0, .45); }
.theme-menu[hidden] { display: none; }
.theme-choice { display: grid; grid-template-columns: 20px 1fr 14px; align-items: center; gap: 10px; padding: 11px 9px; border: 0; border-bottom: 1px solid var(--line); background: transparent; color: var(--paper); cursor: pointer; text-align: left; }
.theme-choice:last-child { border-bottom: 0; }
.theme-choice:hover, .theme-choice.is-active { background: rgba(255, 255, 255, .04); }
.theme-choice strong, .theme-choice small { display: block; }
.theme-choice strong { font: 10px var(--mono); }
.theme-choice small { margin-top: 5px; color: var(--muted); font-size: 8px; }
.theme-swatch { width: 15px; height: 15px; border: 1px solid rgba(255, 255, 255, .35); }
.hacker-swatch { background: radial-gradient(circle, #010602 32%, #20ef4f 100%); box-shadow: 0 0 7px #20ef4f; }
.cyberpunk-swatch { background: radial-gradient(circle, #080406 32%, #ed1b2e 100%); box-shadow: 0 0 7px #ed1b2e; }
.theme-check { color: var(--green); font-size: 12px; opacity: 0; }
.theme-choice.is-active .theme-check { opacity: 1; }
.experience-explorer { display: grid; grid-template-columns: minmax(185px, .7fr) minmax(0, 1.3fr); gap: 20px; align-items: stretch; }
.experience-folders { display: grid; align-content: start; gap: 8px; }
.topic-folder { position: relative; min-height: 74px; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 11px; padding: 12px; border: 1px solid var(--green); border-radius: 5px; background: var(--ink); color: var(--green); cursor: pointer; text-align: left; transition: border-color .2s ease, background .2s ease, transform .2s ease; }
.topic-folder::before { left: 9px; width: 30px; }
.topic-folder:hover, .topic-folder.is-open, .topic-folder:focus-visible { border-color: var(--ink); background: var(--green); color: var(--ink); }
.topic-folder:hover::before, .topic-folder.is-open::before, .topic-folder:focus-visible::before { border-color: var(--ink); background: var(--green); }
.topic-folder.is-open { transform: translateX(5px); }
.topic-folder strong { display: block; color: inherit; font: 11px var(--mono); }
.topic-folder small { display: block; margin-top: 5px; color: var(--green-dim); font-size: 8px; }
.topic-folder:hover small, .topic-folder.is-open small, .topic-folder:focus-visible small { color: var(--ink); opacity: .75; }
.folder-count { color: var(--green); font-size: 8px; }
.topic-folder:hover .folder-count, .topic-folder.is-open .folder-count, .topic-folder:focus-visible .folder-count { color: var(--ink); }
.folder-panel { min-height: 270px; overflow: hidden; border: 1px solid var(--line); background: rgba(13, 16, 14, .72); }
.folder-panel-heading { min-height: 39px; display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 0 14px; border-bottom: 1px solid var(--line); color: var(--green); font-size: 9px; }
.folder-panel-heading span:last-child { color: var(--muted); font-size: 7px; }
.folder-items { display: grid; gap: 9px; padding: 13px; }
.folder-entry { position: relative; display: block; min-width: 0; padding: 12px; border-left: 1px solid var(--green-dim); background: var(--panel-raised); color: var(--paper); text-decoration: none; opacity: 0; clip-path: inset(0 100% 0 0); }
.folder-items.is-opening .folder-entry { animation: folder-type-in .9s steps(32, end) calc(var(--entry-index) * 180ms) forwards; }
@keyframes folder-type-in { 0% { opacity: .45; clip-path: inset(0 100% 0 0); } 100% { opacity: 1; clip-path: inset(0 0 0 0); } }
.folder-entry h4 { margin: 7px 0 5px; color: var(--paper); font: 500 14px var(--display); }
.folder-entry p { margin: 0; color: #aeb5ad; font-size: 9px; line-height: 1.6; }
.folder-entry .card-meta { margin-top: 8px; }
.folder-entry .card-cta { display: inline-block; margin-top: 8px; color: var(--green); font-size: 8px; }

@media (max-width: 760px) {
  .topbar { min-height: 91px; }
  .route-bar { order: 3; width: 100%; margin: 7px 0 0; font-size: 9px; }
  .home-screen.is-active { grid-template-columns: minmax(0, 1fr); align-content: start; gap: 25px; overflow: hidden; }
  .home-screen .hero-topline { margin-bottom: 20px; }
  .home-screen h1 { font-size: clamp(48px, 11vw, 68px); }
  .home-screen .intro { margin-bottom: 0; }
  .home-directory { width: 100%; }
  .menu-item.folder-tile { min-height: 86px; padding: 9px; }
  .directory-hint { margin-top: 10px; }
