.menu-item.folder-tile .folder-file { position: absolute; z-index: 2; bottom: 10px; left: 15px; width: calc(100% - 30px); height: 68%; border: 1px solid var(--line); border-radius: 4px; background: var(--paper); box-shadow: 0 2px 5px rgba(0, 0, 0, .14); opacity: 1; transition: transform .4s ease; }
