  .about-copy { font-size: 10px; line-height: 1.7; }
  .about-copy p { margin-bottom: 11px; }
  .about-copy .quote { padding: 10px; font-size: 9px; }
  .skills-grid { gap: 12px 22px; }
  .skill-row { grid-template-columns: minmax(85px, 1fr) minmax(35px, 1fr) 29px; gap: 6px; }
  .skill-name { font-size: 8px; }
  .experience-columns { gap: 16px; }
  .experience-card, .project-card { padding: 12px; }
  .experience-card h4, .project-card h4 { font-size: 13px; }
  .experience-card p, .project-card p { font-size: 9px; }
  .project-card { min-height: 180px; }
  .contact-layout { grid-template-columns: 1fr; gap: 21px; }
  .contact-list { margin-bottom: 14px; }
}

@media (max-width: 460px) {
  .page-shell { width: calc(100% - 20px); }
  .topbar { min-height: 86px; }
  .status-divider { display: none; }
  .site-nav button { font-size: 7px; }
  .screen { padding: 19px 13px; }
  .home-screen.is-active { align-content: center; }
  .hero-topline { margin-bottom: 20px; font-size: 6px; }
  .home-screen h1 { font-size: clamp(45px, 12vw, 58px); }
  .intro { font-size: 10px; }
  .menu-item { grid-template-columns: 37px 1fr 18px; gap: 7px; min-height: 38px; padding: 0 8px; font-size: 9px; }
  .page-controls { gap: 8px; }
  .page-progress { gap: 5px; }
  #page-dots button { width: 7px; }
  .pager-button span { display: none; }
  .about-layout { grid-template-columns: 1fr; }
  .profile-photo { position: relative; width: min(170px, 55%); }
  .profile-photo img { max-height: 185px; }
  .skills-grid { grid-template-columns: 1fr; gap: 0; }
  .skill-group { padding: 12px 0; }
  .experience-columns { grid-template-columns: 1fr; gap: 20px; }
  .project-grid { grid-template-columns: 1fr; }
  .project-card { min-height: 145px; }
  .keyboard-hint { display: flex; gap: 3px; font-size: 6px; white-space: nowrap; }
}

@media (prefers-reduced-motion: reduce) {
  .screen.is-active { animation: none; }
  .skill-fill { animation: none; }
}

.wordmark { text-decoration: none; }
.route-bar { display: flex; align-items: center; gap: 9px; margin-left: auto; color: var(--green); font-size: 10px; white-space: nowrap; }
.route-prompt { color: var(--muted); }
.route-bar a { color: var(--green); }
.route-bar a:hover { text-decoration: underline; text-underline-offset: 4px; }
#route-page { color: var(--cyan); }
.home-screen.is-active { grid-template-columns: minmax(0, 1.15fr) minmax(270px, .85fr); gap: clamp(28px, 5vw, 72px); overflow: hidden; }
.home-content { min-width: 0; }
.home-directory { align-self: center; min-width: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; perspective: 760px; perspective-origin: center bottom; }
.directory-heading { grid-column: 1 / -1; min-height: 34px; display: flex; align-items: center; justify-content: space-between; gap: 12px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.directory-heading > span:last-child { color: var(--green-dim); font-size: 8px; }
.menu-item.folder-tile { position: relative; min-height: 112px; display: grid; grid-template-columns: minmax(0, 1fr) 18px; grid-template-rows: 1fr auto auto; align-items: end; gap: 5px 8px; padding: 12px; border: 1px solid var(--green); border-radius: 5px; background: var(--ink); color: var(--green); text-decoration: none; perspective: 600px; transform-style: flat; transition: transform .28s ease, border-color .18s ease, background-color .18s ease, color .18s ease; }
.topic-folder::before { position: absolute; top: -7px; left: 12px; width: 36px; height: 7px; border: 1px solid var(--green); border-bottom: 0; border-radius: 5px 5px 0 0; background: var(--ink); content: ""; }
.menu-item.folder-tile .folder-back::before { position: absolute; top: -9px; left: -1px; width: 38%; height: 9px; border: 1px solid var(--green-dim); border-bottom: 0; border-radius: 5px 5px 0 0; background: var(--green-dim); content: ""; }
.menu-item.folder-tile.is-selected, .menu-item.folder-tile.is-option-selected { z-index: 2; border-color: var(--ink); background: transparent; color: var(--ink); }
.menu-item.folder-tile > * { position: relative; z-index: 5; }
.menu-item.folder-tile > .menu-index, .menu-item.folder-tile > .folder-name, .menu-item.folder-tile > .folder-meta, .menu-item.folder-tile > .menu-arrow { position: relative; z-index: 5; }
.menu-item.folder-tile .folder-back { position: absolute; z-index: 1; right: 4px; bottom: 4px; left: 4px; height: 88%; border: 1px solid var(--green-dim); border-radius: 0 8px 8px 8px; background: var(--green-dim); }
.menu-item.folder-tile .folder-file { position: absolute; z-index: 2; bottom: 10px; left: 15px; width: calc(100% - 30px); height: 68%; border: 1px solid var(--line); border-radius: 4px; background: var(--paper); box-shadow: 0 2px 5px rgba(0, 0, 0, .14); opacity: 1; transition: transform .4s ease-in-out; }
.menu-item.folder-tile .folder-file-1 { transform: translateY(0); }
.menu-item.folder-tile .folder-file-2 { transform: translate(5px, -5px) rotate(2deg); }
.menu-item.folder-tile .folder-front { position: absolute; z-index: 4; right: 4px; bottom: 4px; left: 4px; height: 88%; border: 2px solid var(--ink); border-radius: 0 8px 8px 8px; background: var(--green); box-shadow: 0 4px 10px rgba(0, 0, 0, .22); transform: rotateX(0); transform-origin: bottom center; backface-visibility: visible; transition: transform .4s ease-in-out, background-color .4s ease-in-out; }
.menu-item.folder-tile:hover .folder-front, .menu-item.folder-tile:focus .folder-front { transform: rotateX(-40deg); background: color-mix(in srgb, var(--green) 78%, var(--ink)); }
.menu-item.folder-tile:hover .folder-file-1, .menu-item.folder-tile:focus .folder-file-1 { transform: translateY(-20px); }
.menu-item.folder-tile:hover .folder-file-2, .menu-item.folder-tile:focus .folder-file-2 { transform: translateY(-25px) translate(5px, -5px) rotate(4deg); }
.menu-index { grid-column: 2; grid-row: 1; justify-self: end; color: var(--green); font-size: 8px; }
.folder-name { grid-column: 1; grid-row: 2; color: inherit; font-size: 12px; }
.folder-meta { grid-column: 1; grid-row: 3; color: var(--green-dim); font-size: 7px; }
.menu-item.folder-tile .menu-arrow { grid-column: 3; grid-row: 2 / 4; align-self: center; justify-self: end; }
.menu-item.folder-tile .menu-arrow { grid-column: 2; }
.menu-item.folder-tile > .menu-index, .menu-item.folder-tile > .folder-name, .menu-item.folder-tile > .folder-meta, .menu-item.folder-tile > .menu-arrow { color: var(--ink); opacity: 1; transition: opacity .3s ease-in-out; }
.menu-item.folder-tile:hover > .menu-index, .menu-item.folder-tile:hover > .folder-name, .menu-item.folder-tile:hover > .folder-meta, .menu-item.folder-tile:hover > .menu-arrow,
.menu-item.folder-tile:focus > .menu-index, .menu-item.folder-tile:focus > .folder-name, .menu-item.folder-tile:focus > .folder-meta, .menu-item.folder-tile:focus > .menu-arrow { opacity: 0; }
.menu-item.folder-tile.is-selected::before, .menu-item.folder-tile.is-option-selected::before { border-color: var(--ink); background: var(--green); }
.menu-item.folder-tile.is-selected .menu-index, .menu-item.folder-tile.is-option-selected .menu-index,
.menu-item.folder-tile.is-selected .folder-meta, .menu-item.folder-tile.is-option-selected .folder-meta,
.menu-item.folder-tile.is-selected .menu-arrow, .menu-item.folder-tile.is-option-selected .menu-arrow { color: var(--ink); }
.directory-hint { grid-column: 1 / -1; margin: 6px 0 0; color: var(--muted); font-size: 8px; }
.directory-hint kbd { display: inline-block; margin-right: 3px; padding: 3px 5px; border: 1px solid var(--line); color: var(--paper); font: 8px var(--mono); }
.directory-hint kbd:nth-of-type(2) { margin-right: 8px; }
.home-screen .hero-topline { margin-bottom: 31px; }
.home-screen h1 { font-size: clamp(53px, 7vw, 88px); }
.home-screen .intro { font-size: 12px; }
.page-controls { gap: 18px; }
.page-progress { gap: 8px; }
.option-label { color: var(--green-dim); font-size: 8px; }
.keyboard-hint { font-size: 8px; }
.is-option-selected:not(.menu-item) { outline: 1px solid var(--green-dim); outline-offset: 3px; }
.skill-group.is-option-selected { outline-offset: 5px; }
.experience-card.is-option-selected, .project-card.is-option-selected { border-color: var(--green); }
.contact-chip.is-option-selected, .cv-link.is-option-selected { outline-offset: 3px; }

body[data-theme="cyberpunk"] {
  --ink: #080406;
  --panel: #12080a;
  --panel-raised: #1b0b0f;
  --line: #4a1018;
  --muted: #a88487;
  --paper: #f3e7e8;
  --green: #ed1b2e;
  --green-dim: #8b1020;
  --cyan: #ff727b;
  --grid-line: rgba(237, 27, 46, .035);
  --orb-core: #080406;
  --orb-glow: #ed1b2e;
}
.route-bar, .route-bar a, #route-page { color: var(--green); }
.route-bar { gap: 4px; }
.page-controls { justify-content: space-between; }
.keyboard-hint { margin-left: 0; }
.theme-picker { position: relative; z-index: 8; flex: 0 0 56px; margin-left: 0; }
.theme-toggle { width: 56px; min-width: 56px; height: 56px; display: grid; place-items: center; padding: 0; border: 0; background: transparent; cursor: pointer; }
.theme-orb { position: relative; width: 30px; height: 30px; border-radius: 50%; background: radial-gradient(circle, var(--orb-core) 0 39%, color-mix(in srgb, var(--orb-glow) 75%, var(--orb-core)) 74%, var(--orb-glow) 100%); box-shadow: 0 0 13px 3px var(--orb-glow), inset 0 0 12px var(--orb-glow); transition: transform .2s ease, box-shadow .2s ease; }
.theme-orb::before { position: absolute; inset: -7px; border: 1px solid var(--green); border-radius: 50%; content: ""; }
.theme-toggle:hover .theme-orb, .theme-toggle[aria-expanded="true"] .theme-orb { transform: scale(1.06); box-shadow: 0 0 18px 4px var(--orb-glow), inset 0 0 12px var(--orb-glow); }
.theme-menu { position: absolute; left: 0; bottom: calc(100% + 8px); width: 240px; display: grid; padding: 5px; border: 1px solid var(--green); background: var(--panel-raised); box-shadow: 0 12px 28px rgba(0, 0, 0, .45); }
.theme-menu[hidden] { display: none; }
.theme-choice { display: grid; grid-template-columns: 20px 1fr 14px; align-items: center; gap: 10px; padding: 11px 9px; border: 0; border-bottom: 1px solid var(--line); background: transparent; color: var(--paper); cursor: pointer; text-align: left; }
.theme-choice:last-child { border-bottom: 0; }
.theme-choice:hover, .theme-choice.is-active { background: rgba(255, 255, 255, .04); }
.theme-choice strong, .theme-choice small { display: block; }
.theme-choice strong { font: 10px var(--mono); }
.theme-choice small { margin-top: 5px; color: var(--muted); font-size: 8px; }
.theme-swatch { width: 15px; height: 15px; border: 1px solid rgba(255, 255, 255, .35); }
.hacker-swatch { background: radial-gradient(circle, #010602 32%, #20ef4f 100%); box-shadow: 0 0 7px #20ef4f; }
.cyberpunk-swatch { background: radial-gradient(circle, #080406 32%, #ed1b2e 100%); box-shadow: 0 0 7px #ed1b2e; }
.theme-check { color: var(--green); font-size: 12px; opacity: 0; }
.theme-choice.is-active .theme-check { opacity: 1; }
.experience-explorer { display: grid; grid-template-columns: minmax(185px, .7fr) minmax(0, 1.3fr); gap: 20px; align-items: stretch; }
.experience-folders { display: grid; align-content: start; gap: 8px; }
.topic-folder { position: relative; min-height: 74px; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 11px; padding: 12px; border: 1px solid var(--green); border-radius: 5px; background: var(--ink); color: var(--green); cursor: pointer; text-align: left; transition: border-color .2s ease, background .2s ease, transform .2s ease; }
.topic-folder::before { left: 9px; width: 30px; }
.topic-folder:hover, .topic-folder.is-open, .topic-folder:focus-visible { border-color: var(--ink); background: var(--green); color: var(--ink); }
.topic-folder:hover::before, .topic-folder.is-open::before, .topic-folder:focus-visible::before { border-color: var(--ink); background: var(--green); }
.topic-folder.is-open { transform: translateX(5px); }
.topic-folder strong { display: block; color: inherit; font: 11px var(--mono); }
.topic-folder small { display: block; margin-top: 5px; color: var(--green-dim); font-size: 8px; }
.topic-folder:hover small, .topic-folder.is-open small, .topic-folder:focus-visible small { color: var(--ink); opacity: .75; }
.folder-count { color: var(--green); font-size: 8px; }
.topic-folder:hover .folder-count, .topic-folder.is-open .folder-count, .topic-folder:focus-visible .folder-count { color: var(--ink); }
.folder-panel { min-height: 270px; overflow: hidden; border: 1px solid var(--line); background: rgba(13, 16, 14, .72); }
.folder-panel-heading { min-height: 39px; display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 0 14px; border-bottom: 1px solid var(--line); color: var(--green); font-size: 9px; }
.folder-panel-heading span:last-child { color: var(--muted); font-size: 7px; }
.folder-items { display: grid; gap: 9px; padding: 13px; }
.folder-entry { position: relative; display: block; min-width: 0; padding: 12px; border-left: 1px solid var(--green-dim); background: var(--panel-raised); color: var(--paper); text-decoration: none; opacity: 0; clip-path: inset(0 100% 0 0); }
.folder-items.is-opening .folder-entry { animation: folder-type-in .9s steps(32, end) calc(var(--entry-index) * 180ms) forwards; }
@keyframes folder-type-in { 0% { opacity: .45; clip-path: inset(0 100% 0 0); } 100% { opacity: 1; clip-path: inset(0 0 0 0); } }
.folder-entry h4 { margin: 7px 0 5px; color: var(--paper); font: 500 14px var(--display); }
.folder-entry p { margin: 0; color: #aeb5ad; font-size: 9px; line-height: 1.6; }
.folder-entry .card-meta { margin-top: 8px; }
.folder-entry .card-cta { display: inline-block; margin-top: 8px; color: var(--green); font-size: 8px; }

@media (max-width: 760px) {
  .topbar { min-height: 91px; }
  .route-bar { order: 3; width: 100%; margin: 7px 0 0; font-size: 9px; }
  .home-screen.is-active { grid-template-columns: minmax(0, 1fr); align-content: start; gap: 25px; overflow: hidden; }
  .home-screen .hero-topline { margin-bottom: 20px; }
  .home-screen h1 { font-size: clamp(48px, 11vw, 68px); }
  .home-screen .intro { margin-bottom: 0; }
  .home-directory { width: 100%; }
  .menu-item.folder-tile { min-height: 86px; padding: 9px; }
  .directory-hint { margin-top: 10px; }
  .page-controls { gap: 12px; }
  .keyboard-hint { gap: 4px; font-size: 7px; }
  .keyboard-hint kbd { min-width: 17px; }
  .keyboard-hint .hint-divider { display: none; }
  .experience-explorer { grid-template-columns: 165px minmax(0, 1fr); gap: 12px; }
  .topic-folder { grid-template-columns: 20px minmax(0, 1fr); min-height: 60px; gap: 8px; padding: 8px; }
  .topic-folder .folder-count { display: none; }
  .topic-folder small { font-size: 7px; }
  .folder-panel { min-height: 230px; }
}

@media (max-width: 460px) {
  .route-bar { gap: 6px; font-size: 8px; }
  .home-screen.is-active { gap: 17px; }
  .home-screen .hero-topline { gap: 6px 10px; margin-bottom: 16px; font-size: 6px; }
  .home-screen h1 { font-size: clamp(43px, 11vw, 54px); }
  .menu-item { min-height: 39px; padding: 0 8px; font-size: 9px; }
  .page-controls { gap: 8px; }
  .keyboard-hint { gap: 3px; flex: 1; justify-content: flex-start; font-size: 6px; white-space: nowrap; }
  .keyboard-hint .hint-divider { display: none; }
  .theme-menu { width: min(235px, calc(100vw - 30px)); }
  .experience-explorer { grid-template-columns: 1fr; }
  .experience-folders { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 5px; }
  .topic-folder { grid-template-columns: 16px minmax(0, 1fr); min-height: 57px; gap: 6px; padding: 7px 5px; }
  .topic-folder .folder-icon { width: 15px; height: 11px; }
  .topic-folder .folder-icon::before { width: 7px; height: 3px; top: -4px; }
  .topic-folder strong { font-size: 8px; }
  .topic-folder small { overflow: hidden; font-size: 6px; text-overflow: ellipsis; white-space: nowrap; }
  .folder-panel { min-height: 220px; }
}

@media (max-height: 700px) {
  .home-screen.is-active { gap: 12px; padding: 12px 14px; }
  .home-screen .hero-topline { margin-bottom: 8px; }
  .home-screen .eyebrow { margin-bottom: 6px; }
  .home-screen h1 { font-size: clamp(38px, 6vh, 52px); }
  .home-screen .hero-role { margin: 7px 0; }
  .home-screen .intro { margin: 8px 0 0; font-size: 9px; line-height: 1.35; }
  .menu-item.folder-tile { min-height: 60px; grid-template-columns: 23px minmax(0, 1fr) 14px; gap: 3px 6px; padding: 6px; }
  .menu-item.folder-tile .folder-icon { width: 19px; height: 13px; }
  .menu-item.folder-tile .folder-icon::before { top: -4px; width: 7px; height: 3px; }
  .folder-name { font-size: 9px; }
  .folder-meta { font-size: 6px; }
  .directory-heading { min-height: 24px; }
  .directory-hint { margin-top: 3px; font-size: 7px; }
}

@media (max-height: 560px) {
  .page-shell { min-height: 0; }
  .topbar { min-height: 68px; padding-top: 6px; padding-bottom: 3px; }
  .route-bar { order: 0; width: auto; margin: 0 0 0 auto; font-size: 7px; }
  .system-status { font-size: 7px; }
  .page-controls { min-height: 42px; }
  .home-screen.is-active { gap: 8px; }
  .menu-item.folder-tile { min-height: 50px; }
  .directory-heading { min-height: 21px; }
  .directory-hint { margin-top: 1px; }
}

@media (prefers-reduced-motion: reduce) {
  .menu-item.folder-tile .folder-front, .menu-item.folder-tile .folder-file { transition: none; }
  .folder-items.is-opening .folder-entry { animation-duration: .01ms; }
}

