  moveOption(direction) {
    const options = View.getOptions();
    if (!options.length) return;
    Model.state.optionIndex = View.setOptionIndex(Model.state.optionIndex + direction);
  },

  bindNavigation() {
    document.addEventListener("click", (event) => {
      const routeControl = event.target.closest("[data-route]");
      const optionControl = event.target.closest("[data-option-step]");

      if (routeControl) {
        event.preventDefault();
        this.goTo(routeControl.dataset.route);
      } else if (optionControl) {
        this.moveOption(Number(optionControl.dataset.optionStep));
      }
    });

    View.els.menuItems.forEach((item, index) => {
      const selectItem = () => {
        Model.state.menuIndex = index;
        Model.state.optionIndex = index;
        View.setMenuSelection(index);
      };
      item.addEventListener("focus", selectItem);
      item.addEventListener("mouseenter", selectItem);
    });
  },

  bindKeyboard() {
    document.addEventListener("keydown", (event) => {
      const isTyping = event.target.matches("input, textarea, select, [contenteditable='true']");
      if (isTyping && event.key !== "Escape") return;

      const themeMenuOpen = !View.els.themeMenu.hidden;
      if (themeMenuOpen && event.key === "Escape") {
        event.preventDefault();
        View.setThemeMenuOpen(false, true);
        return;
      }
      if (themeMenuOpen && ["ArrowUp", "ArrowDown"].includes(event.key)) {
        event.preventDefault();
        const choices = View.els.themeChoices;
        const currentIndex = choices.indexOf(document.activeElement);
        const direction = event.key === "ArrowDown" ? 1 : -1;
        choices[(currentIndex + direction + choices.length) % choices.length].focus();
        return;
      }
      if (themeMenuOpen && ["ArrowLeft", "ArrowRight"].includes(event.key)) {
        event.preventDefault();
        return;
      }

      if (!isTyping && event.key.toLowerCase() === "t") {
        event.preventDefault();
        View.setThemeMenuOpen(true);
      } else if (event.key === "Escape") {
        event.preventDefault();
        this.goTo("home");
      } else if (["ArrowDown", "ArrowRight"].includes(event.key)) {
        event.preventDefault();
        this.moveOption(1);
      } else if (["ArrowUp", "ArrowLeft"].includes(event.key)) {
        event.preventDefault();
        this.moveOption(-1);
      }
    });
  },

  bindThemeMenu() {
    View.els.themeToggle.addEventListener("click", () => {
      View.setThemeMenuOpen(View.els.themeMenu.hidden);
    });

    View.els.themeChoices.forEach((choice) => {
      choice.addEventListener("click", () => {
        View.setTheme(choice.dataset.themeChoice);
        View.setThemeMenuOpen(false, true);
      });
    });

    document.addEventListener("click", (event) => {
      if (!event.target.closest(".theme-picker")) View.setThemeMenuOpen(false);
    });
  },

