    if (option.dataset.folder) this.renderExperienceFolder(option.dataset.folder);
    if (document.activeElement !== option && !option.matches("input, textarea")) option.focus({ preventScroll: true });
    Model.state.optionIndex = index;
    if (Model.state.screen === "home") Model.state.menuIndex = index;
  },

  setMenuSelection(index) {
    this.setOptionIndex(index, false);
  },

  renderSkills(groups) {
    const fragment = document.createDocumentFragment();
    groups.forEach((group) => {
      const section = document.createElement("section");
      section.className = "skill-group";
      section.tabIndex = -1;
      const heading = document.createElement("h3");
      heading.textContent = group.group;
      section.append(heading);

      group.items.forEach(([name, value]) => {
        const row = document.createElement("div");
        row.className = "skill-row";
